import java.util.ArrayList;
import java.util.HashSet;
public class BikeDemo
{
    public static void main(String[] args)
    {
        ArrayList<Bike> fleet = new ArrayList<>();
        fleet.add(new Bike("B1", 4));
        fleet.add(new Bike("B2", 5));
        fleet.add(new EBike("E1", 6));
        for(Bike bike : fleet) {
            System.out.println(bike + ": 3 hours, $" + bike.cost(3));
        }
        Bike returned = new Bike("B1", 4);
        System.out.println(fleet.get(0).equals(returned));
        HashSet<Bike> out = new HashSet<>();
        out.add(fleet.get(0));
        out.add(fleet.get(2));
        out.add(returned);
        System.out.println("Bikes out: " + out.size());
    }
}

