{
    private String seat;
    private int price;
    public Ticket(String seat, int price)
    {
        this.seat = seat;
        this.price = price;
    }
    public String getSeat()
    {
        return seat;
    }
    public int getPrice()
    {
        return price;
    }
    @Override
    public String toString()
    {
        return seat + ": " + price + " dollars";
    }
    @Override
    public boolean equals(Object obj)
    {
        if(this == obj) {
            return true;
        }
        if(!(obj instanceof Ticket)) {
            return false;
        }
        Ticket other = (Ticket) obj;
        return seat.equals(other.seat);
    }
